#!/usr/bin/env python3
"""Decode folder-bag localization protobuf streams to compact JSON."""

import argparse
import json
import struct
from pathlib import Path

try:
    from adas_spec.vehicle.atom.adcu.bag_pb2 import TopicData
    from adas_spec.vehicle.atom.adcu.common_pb2 import EgoPose
    from adas_spec.vehicle.atom.adcu.localization_pb2 import EgoPoseFused
except ImportError:
    # Supports protobuf modules freshly generated by protoc in OpenMMLab.
    from vehicle.atom.adcu.bag_pb2 import TopicData
    from vehicle.atom.adcu.common_pb2 import EgoPose
    from vehicle.atom.adcu.localization_pb2 import EgoPoseFused


def samples(folder, message_type):
    rows = []
    for bin_path in sorted(folder.glob("*.bin")):
        data = TopicData()
        data.ParseFromString(bin_path.read_bytes())
        index = bin_path.with_suffix(".idx").read_bytes()
        for number, sample in enumerate(data.samples):
            message = message_type()
            message.ParseFromString(sample.data)
            wall_ns = struct.unpack_from("<Q", index, number * 8)[0]
            if message_type is EgoPoseFused:
                rows.append([wall_ns, int(message.timestamp),
                             float(message.position.x), float(message.position.y),
                             float(message.orientation.yaw),
                             float(message.velocity.x), float(message.velocity.y),
                             int(message.status)])
            else:
                rows.append([wall_ns, int(message.timestamp),
                             float(message.pose.position.x),
                             float(message.pose.position.y),
                             float(message.pose.orientation), 0.0, 0.0,
                             int(message.status)])
    return rows


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("bag", type=Path)
    parser.add_argument("output", type=Path)
    args = parser.parse_args()
    root = args.bag
    fused = root / "__engineering__adcu__debug__ZMQ__Localization__FusedOdometry"
    odometry = root / "__engineering__adcu__debug__ZMQ__Localization__Odometry"
    result = {
        "columns": ["wall_ns", "message_ms", "x", "y", "yaw", "vx", "vy", "status"],
        "fused": samples(fused, EgoPoseFused),
        "odometry": samples(odometry, EgoPose),
    }
    args.output.write_text(json.dumps(result, separators=(",", ":")))
    print(json.dumps({"fused": len(result["fused"]),
                      "odometry": len(result["odometry"]),
                      "output": str(args.output)}, indent=2))


if __name__ == "__main__":
    main()
